        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let provider = DeviceIdentity::generate();
        let provider_key = provider.public().x25519_pub;
        servers.spawn(async move {
            let (socket, _) = listener.accept().await.unwrap();
            let mut session =
                PeerSession::accept(socket, &provider.secret_bytes().1, |peer| *peer == reader_key)
                    .await
                    .unwrap();
            for round in 0..3 {
                if lane == 0 && round > 0 {
                    tokio::time::sleep(Duration::from_millis(25)).await;
                }
                serve_post_body_request(
                    &mut session,
                    |peer, object, index, length| {
                        assert_eq!((*peer, object, length), (reader_key, checksum, 5));
                        assert_eq!(index % 2, lane);
                        Some(chunks[index as usize].to_vec())
                    },
                    |peer, object, start, length| {
                        assert_eq!((*peer, object, start, length), (reader_key, checksum, 0, 4));
                        Some((0..4).map(|index| index % 2 == lane).collect())
                    },
                )
                .await
                .unwrap();
            }
        });
        let stream = TcpStream::connect(address).await.unwrap();
        let session = PeerSession::connect(stream, &reader.secret_bytes().1, &provider_key)
            .await
            .unwrap();
        sources.push(
            SessionChunkSource::discover(checksum, 4, 4, session, Duration::from_secs(2))
                .await
                .unwrap(),
        );
    }

    download_post_body(
        PostBodyManifest {
            bytes: 20,
            chunk_bytes: 5,
            checksum,
            chunk_hashes: &hashes,
        },
        staging.path(),
        &sources,
        20,
        4,
        NonZeroUsize::new(4).unwrap(),
    )
    .await
    .unwrap();
    while let Some(result) = servers.join_next().await {
        result.unwrap();
    }
    for (index, chunk) in chunks.iter().enumerate() {
        assert_eq!(std::fs::read(staging.path().join(index.to_string())).unwrap(), *chunk);
    }
}
