 let now=SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();
 let mut query=connection.prepare("SELECT hex(id),hex(conversation),hex(wall_clock),kind,commit_ordinal FROM retained_events WHERE wall_clock>=?1 ORDER BY wall_clock DESC LIMIT 64")?;
 for row in query.query_map(params![now.saturating_sub(window).to_be_bytes().as_slice()],|r| Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?,r.get::<_,String>(2)?,r.get::<_,i64>(3)?,r.get::<_,i64>(4)?)))? {
 let (id,scope,clock,kind,ordinal)=row?;
 println!("{} {} {} {} {}",u64::from_str_radix(&clock,16)?,id,scope,kind,ordinal);
 }
 Ok(())
}
