                let (_, evidence) = observations.custody.get(id)?;
                let evidence: Vec<_> = evidence.iter().filter(|fact|
                    self.observed_destination_current(&store, *id, fact.original)
                ).cloned().collect();
                (!evidence.is_empty()).then_some((*id, evidence))
            }).collect()
        };
        if facts.is_empty() {
            return BTreeMap::new();
